def check_login(attempts: int) -> str:
    if attempts >= 5:
        return "locked"
    return "allowed"

def test_positive():
    assert check_login(4) == "allowed"

def test_boundary():
    assert check_login(4) == "allowed"
    assert check_login(5) == "locked"
    assert check_login(6) == "locked"

def test_negative():
    with pytest.raises(Exception):
        check_login(-1)

def test_edge():
    assert check_login(1000000) == "locked"
